1	import { initializeInteractionAnalytics } from './services/interactionAnalytics';
2	
3	const isNative = typeof window !== 'undefined' && '__TAURI_INTERNALS__' in window;
4	const params = new URLSearchParams(window.location.search);
5	const hasAppEntry = params.get('app') === '1';
6	const offer = params.get('offer');
7	const hasValidOffer = offer === 'reading' || offer === 'conversation';
8	const isAppDocument = window.location.pathname === '/app.html';
9	
10	if (!isAppDocument && !isNative) {
11	  const destination = new URL(window.location.href);
12	  destination.pathname = hasAppEntry || hasValidOffer ? '/app.html' : '/marketing.html';
13	  window.location.replace(destination.href);
14	} else {
15	  Promise.all([
16	    import('react-dom/client'),
17	    import('./App.tsx'),
18	    import('./components/PurchaseAccess'),
19	    import('./components/VoiceDownloadStatus'),
20	    import('./components/BuildStamp'),
21	    import('./index.css'),
22	  ])
23	    .then(([{ createRoot }, { default: App }, { PurchaseAccessProvider }, { VoiceDownloadStatus }, { BuildStamp }, ,]) => {
24	      createRoot(document.getElementById('root')!).render(
25	        <PurchaseAccessProvider>
26	          <App />
27	          <VoiceDownloadStatus />
28	          <BuildStamp />
29	        </PurchaseAccessProvider>,
30	      );
31	      try { initializeInteractionAnalytics('app'); }
32	      catch { console.error('Interaction analytics initialization failed (VITE_GA_MEASUREMENT_ID).'); }
33	    })
34	    .catch((err) => {
35	      const root = document.getElementById('root');
36	      if (root) {
37	        root.textContent = 'Failed to load the app. ';
38	        const link = document.createElement('a');
39	        link.href = window.location.href;
40	        link.textContent = 'Reload';
41	        root.appendChild(link);
42	      }
43	      console.error(err);
44	    });
45	}
