3	import { execFileSync } from 'node:child_process';
4	import { releaseBuildInfo } from './release-state.mjs';
5	import { generatePwa } from './pwa-build.mjs';
6	const release = releaseBuildInfo();
7	const currentDocument = (path, mount) => existsSync(path) && readFileSync(path, 'utf8').includes(`content="${release.invocationId}"`) && readFileSync(path, 'utf8').includes(`id="${mount}"`);
8	if (currentDocument('dist-web/app.html', 'root') && currentDocument('dist-web/marketing.html', 'marketing-experience-root') && currentDocument('dist-web/index.html', 'marketing-experience-root')) {
9	  console.log(`Reusing the frozen web bundle for v${release.version}`);
10	} else {
11	  execFileSync(process.execPath, ['node_modules/vite/bin/vite.js', 'build'], { stdio: 'inherit', env: process.env });
12	  if (!currentDocument('dist-web/index.html', 'root') || !currentDocument('dist-web/marketing.html', 'marketing-experience-root')) throw new Error('The compiled app and landing must match the frozen release before entry routing is prepared.');
13	  copyFileSync('dist-web/index.html', 'dist-web/app.html');
14	  copyFileSync('dist-web/marketing.html', 'dist-web/index.html');
15	}
