13	const stageIndexPath = join(stageDir, "index.html");
14	const stageIndexHash = sha256(readFileSync(stageIndexPath));
15	if (stageIndexHash !== "e3ad942d63bf7dc179688ac845c739212ad133fc26842ff4dc1976dbdd062baa") {
16	  throw new Error(`staged index.html hash mismatch: ${stageIndexHash}`);
17	}
