19	const marketingPath = join(builtDir, "marketing.html");
20	if (!existsSync(marketingPath)) throw new Error(`missing built marketing.html: ${marketingPath}`);
21	
22	const marketing = readFileSync(marketingPath, "utf8");
23	if (!marketing.includes("natally-version")) throw new Error("marketing.html missing natally-version");
24	if (marketing.includes("/src/marketing.tsx")) throw new Error("marketing.html has raw /src/marketing.tsx reference");
