1	import { readdirSync, statSync, writeFileSync, existsSync } from 'node:fs';
2	import { join, posix } from 'node:path';
3	
4	const SHELL_FILES = new Set(['index.html', 'app.html', 'marketing.html', 'manifest.webmanifest', 'pwa.js']);
5	const BRANDING_ICONS = new Set(['/branding/192x192.png', '/branding/512x512.png']);
6	const ASSET_EXTS = new Set(['.js', '.css', '.wasm']);
7	
8	function walk(dir, base, out) {
9	  for (const entry of readdirSync(dir)) {
10	    const full = join(dir, entry);
11	    const rel = posix.join(base, entry);
12	    const st = statSync(full);
13	    if (st.isDirectory()) walk(full, rel, out);
14	    else out.push('/' + rel.split('\\').join('/'));
15	  }
16	}
17	
18	export function generatePwa(outputDir, release) {
19	  if (!release || !release.version || !release.invocationId) {
20	    throw new Error('generatePwa requires release.version and release.invocationId');
21	  }
22	  if (!existsSync(outputDir)) {
23	    throw new Error(`output dir not found: ${outputDir}`);
24	  }
25	
26	  const all = [];
27	  walk(outputDir, '', all);
28	
29	  const precache = all.filter((url) => {
30	    const path = url.slice(1);
31	    const ext = posix.extname(path).toLowerCase();
32	    if (SHELL_FILES.has(path)) return true;
33	    if (BRANDING_ICONS.has(url)) return true;
34	    if (path.startsWith('branding/')) return false;
35	    return path.startsWith('assets/') && ASSET_EXTS.has(ext);
36	  }).sort();
37	
38	  for (const url of [...SHELL_FILES].map(x => '/' + x).concat([...BRANDING_ICONS])) {
39	    if (!precache.includes(url)) throw new Error('Missing PWA shell resource: ' + url);
40	  }
41	
42	  const cacheName = `natally-shell-${release.version}-${release.invocationId}`;
43	  const list = JSON.stringify(precache);
44	  const sw = String.raw`const RELEASE_ID=${JSON.stringify(release.invocationId)};
45	const CACHE_NAME=${JSON.stringify(cacheName)};
46	const PRECACHE_URLS=${list};
47	const SHELL_ROUTES = new Map([['/', '/index.html'], ['/index.html', '/index.html'], ['/app.html', '/app.html'], ['/marketing.html', '/marketing.html']]);
48	const clientReleases = new Map();
49	const requestedClients = new Set();
50	let pruning = Promise.resolve();
51	
52	async function matchesReleaseHtml(response, releaseId) {
53	  if (!response.ok || !/^(?:text\/html|application\/xhtml\+xml)(?:\s*;|$)/i.test(response.headers.get('content-type') || '')) return false;
54	  const html = await response.clone().text();
55	  for (const tag of html.match(/<meta\b[^>]*>/gi) || []) {
56	    if (!/\sname\s*=\s*(["'])natally-release-id\1/i.test(tag)) continue;
57	    const content = tag.match(/\scontent\s*=\s*(["'])(.*?)\1/i);
58	    if (content && content[2].trim()) return !releaseId || content[2].trim() === releaseId;
59	  }
60	  return false;
61	}
62	
63	self.addEventListener('install', (event) => {
64	  event.waitUntil((async () => {
65	    const existed = await caches.has(CACHE_NAME);
66	    try {
67	      const cache = await caches.open(CACHE_NAME);
68	      const results = await Promise.allSettled(PRECACHE_URLS.map(async (path) => {
69	        const response = await fetch(new Request(path, { cache: 'reload' }));
70	        if (!response.ok) throw new Error('Precache request failed: ' + path);
71	        if (Array.from(SHELL_ROUTES.values()).includes(path) && !await matchesReleaseHtml(response, RELEASE_ID)) throw new Error('Precache invocation mismatch: ' + path);
72	        await cache.put(path, response);
73	      }));
74	      const failed = results.find(result => result.status === 'rejected');
75	      if (failed) throw failed.reason;
76	      await self.skipWaiting();
77	    } catch (error) {
78	      if (!existed) await caches.delete(CACHE_NAME);
79	      throw error;
80	    }
81	  })());
82	});
83	
84	function olderShell(name) {
85	  const own = CACHE_NAME.match(/^natally-shell-(\d+)\.(\d+)\.(\d+)-/);
86	  const candidate = name.match(/^natally-shell-(\d+)\.(\d+)\.(\d+)-/);
87	  if (!own || !candidate) return false;
88	  for (let index = 1; index <= 3; index++) {
89	    if (Number(candidate[index]) !== Number(own[index])) return Number(candidate[index]) < Number(own[index]);
90	  }
91	  // A same/newer-version cache may belong to a worker still installing.
92	  return false;
93	}
94	
95	function pruneUnusedShells() {
96	  const task = pruning.catch(() => {}).then(async () => {
97	    const unknownWindows = async () => {
98	      const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
99	      const liveIds = new Set(windows.map(client => client.id));
100	      for (const id of clientReleases.keys()) if (!liveIds.has(id)) clientReleases.delete(id);
101	      for (const id of requestedClients) if (!liveIds.has(id)) requestedClients.delete(id);
102	      let unknown = false;
103	      for (const client of windows) {
104	        if (clientReleases.has(client.id)) continue;
105	        unknown = true;
106	        if (!requestedClients.has(client.id)) {
107	          requestedClients.add(client.id);
108	          client.postMessage({ type: 'natally:request-release' });
109	        }
110	      }
111	      return unknown;
112	    };
113	    if (await unknownWindows()) return;
114	    const names = await caches.keys();
115	    for (const name of names.filter(olderShell)) {
116	      if (await unknownWindows()) return;
117	      // Read the live reports immediately before deletion. Serialized passes
118	      // cannot use an earlier snapshot after a newly reported document release.
119	      if (Array.from(clientReleases.values()).some(id => name.endsWith('-' + id))) continue;
120	      await caches.delete(name);
121	    }
122	  });
123	  pruning = task;
124	  return task;
125	}
126	
127	self.addEventListener('message', (event) => {
128	  const source = event.source, data = event.data;
129	  if (!source || source.type !== 'window' || !source.id || new URL(source.url).origin !== self.location.origin || data?.type !== 'natally:document-release' || typeof data.releaseId !== 'string' || !data.releaseId.trim()) return;
130	  clientReleases.set(source.id, data.releaseId.trim());
131	  event.waitUntil(pruneUnusedShells());
132	});
133	
134	self.addEventListener('activate', (event) => {
135	  event.waitUntil((async () => {
136	    await self.clients.claim();
137	    await pruneUnusedShells();
138	  })());
139	});
140	
141	async function respondToNavigation(request, shell) {
142	  try {
143	    const response = await fetch(new Request(request, { cache: 'reload' }));
144	    if (!await matchesReleaseHtml(response)) throw new Error('Navigation did not return a release-marked HTML document.');
145	    if (await matchesReleaseHtml(response, RELEASE_ID)) {
146	      try { await (await caches.open(CACHE_NAME)).put(shell, response.clone()); } catch (_) { /* The valid online document is still usable if storage is unavailable. */ }
147	    }
148	    return response;
149	  } catch (error) {
150	    const cached = await (await caches.open(CACHE_NAME)).match(shell);
151	    if (cached) return cached;
152	    throw error;
153	  }
154	}
155	
156	async function retainedAsset(request) {
157	  const path = new URL(request.url).pathname;
158	  const current = await (await caches.open(CACHE_NAME)).match(path);
159	  if (current) return current;
160	  for (const name of (await caches.keys()).filter(name => name.startsWith('natally-shell-') && name !== CACHE_NAME)) {
161	    const retained = await (await caches.open(name)).match(path);
162	    if (retained) return retained;
163	  }
164	  return fetch(request);
165	}
166	
167	self.addEventListener('fetch', (event) => {
168	  const request = event.request;
169	  if (request.method !== 'GET') return;
170	  const url = new URL(request.url);
171	  if (url.origin !== self.location.origin) return;
172	  const shell = SHELL_ROUTES.get(url.pathname);
173	  if (shell && request.mode === 'navigate') {
174	    if (event.clientId) { clientReleases.delete(event.clientId); requestedClients.delete(event.clientId); }
175	    if (event.resultingClientId) { clientReleases.delete(event.resultingClientId); requestedClients.delete(event.resultingClientId); }
176	    const response = respondToNavigation(request, shell);
177	    event.respondWith(response);
178	    event.waitUntil(response.then(() => pruneUnusedShells(), () => pruneUnusedShells()));
179	    return;
180	  }
181	  if (url.pathname.startsWith('/assets/') && /\.(?:js|css|wasm)$/i.test(url.pathname)) {
182	    event.respondWith(retainedAsset(request));
183	    return;
184	  }
185	  if (PRECACHE_URLS.includes(url.pathname)) {
186	    event.respondWith(caches.open(CACHE_NAME).then(cache => cache.match(url.pathname)).then((hit) => hit || fetch(request)));
187	    return;
188	  }
189	});
190	`;
191	
192	  writeFileSync(join(outputDir, 'sw.js'), sw);
193	  writeFileSync(join(outputDir, 'pwa-build.json'), JSON.stringify({
194	    version: release.version,
195	    invocationId: release.invocationId,
196	    cacheName,
197	    precache,
198	  }, null, 2) + '\n');
199	
200	  return { cacheName, precache };
201	}
