8	/** Application identity is deliberately configured in .env, never inherited from a fallback. */
9	export function loadAppIdentity(root = repository) {
10	  const envFile = path.join(root, '.env');
11	  if (!existsSync(envFile)) throw new Error('Configure APP_NAME and APP_IDENTIFIER in .env before using this application.');
