})();
const escapeHtmlText = (value) => value.replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
const legacyRedirectDocument = () => `<!doctype html>
<html lang="en">
